/**
 * Long-horizon refactor: one hard multi-file contract change under a wall-clock cap, n=1 per model, scored on the file diff against a committed reference.
 * Receipt: `benchmarks/longhorizon/results/summary.json`
 * Canonical run: `benchmarks/longhorizon/results` — no `rerun-*` directory exists for this track, so the base receipt is the record.
 * Fields: durS = `durationS`; files = `diff.filesChanged`; inTok = `session.input`; cacheRead = `session.cacheRead`; jaccard = `similarity.fileSetJaccard` (0-1), 2dp
 */
export interface LonghorizonRow {
  /** Model id as routed by llm-bridge; the row order matches the section's bars. */
  model: BenchModel;
  /** Wall-clock seconds under the cap. */
  durS: number;
  /** Files changed against the pristine workspace. */
  files: number;
  /** Billed input tokens. */
  inTok: number;
  /** Cache-read tokens — 0 means nothing was reused. */
  cacheRead: number;
  /** Changed-file-set Jaccard against the committed reference (0-1). */
  jaccard: number;
}

